'use client';
import { pagination } from "@digdir/designsystemet-web";
import { useMemo } from "react";
//#region src/utilities/hooks/use-pagination/use-pagination.ts
/**
* Hook to help manage pagination state
*
* @example
* const { pages, nextButtonProps, prevButtonProps } = usePagination({
*   currentPage: page,
*   totalPages: 10,
*   showPages: 7,
*   setCurrentPage,
* })
*
* <Pagination>
*   <Pagination.Item>
*     <Pagination.Button {...prevButtonProps}>Forrige</Pagination.Button>
*   </Pagination.Item>
*   {pages.map(({ page, itemKey, buttonProps }) => (
*     <Pagination.Item key={itemKey}>
*       {typeof page === 'number' && (
*         <Pagination.Button {...buttonProps} aria-label={`Side ${page}`}>
*           {page}
*         </Pagination.Button>
*       )}
*     </Pagination.Item>
*   ))}
*   <Pagination.Item>
*     <Pagination.Button {...nextButtonProps}>Neste</Pagination.Button>
*   </Pagination.Item>
* </Pagination>
**/
const usePagination = ({ currentPage: current = 1, setCurrentPage, onChange, totalPages: total = 1, showPages: show = 7 }) => useMemo(() => {
	const { next, prev, pages } = pagination({
		current,
		total,
		show
	});
	const handleClick = (page) => (event) => {
		if (page < 1 || page > total) return event.preventDefault();
		onChange?.(event, page);
		if (!event.defaultPrevented) setCurrentPage?.(page);
	};
	return {
		/** Number of steps */
		pages: pages.map(({ page, current }, index) => ({
			/**
			* Page number or "ellipsis" for the ellipsis item
			*/
			page: page || "ellipsis",
			/**
			* Unique key for the item
			*/
			itemKey: page ? `page-${page}` : `ellipsis-${index}`,
			/**
			* Properties to spread on Pagination.Button
			*/
			buttonProps: page ? {
				"aria-current": current ? "true" : void 0,
				onClick: handleClick(page)
			} : null
		})),
		/** Properties to spread on Pagination.Button used for previous navigation */
		prevButtonProps: {
			"aria-hidden": !prev,
			onClick: handleClick(prev)
		},
		/** Properties to spread on Pagination.Button used for next navigation */
		nextButtonProps: {
			"aria-hidden": !next,
			onClick: handleClick(next)
		},
		/** Indication if previous page action should be shown or not */
		hasPrev: !!prev,
		/** Indication if next page action should be shown or not */
		hasNext: !!next
	};
}, [
	current,
	total,
	show
]);
//#endregion
export { usePagination };
