'use client';
import "@digdir/designsystemet-web";
import cl from "clsx/lite";
import { forwardRef } from "react";
import { jsx } from "react/jsx-runtime";
//#region src/components/search/search.tsx
/**
* Search component, use to display different variations of a search input
*
* @example with button
* <Search>
*   <Search.Input aria-label='Søk' />
*   <Search.Clear />
*   <Search.Button />
* </Search>
*
* @example with icon
* <Search>
*   <Search.Input aria-label='Søk' />
*   <Search.Clear />
* </Search>
*/
const Search = forwardRef(function Search({ className, ...rest }, ref) {
	return /* @__PURE__ */ jsx("ds-suggestion", {
		ref,
		class: cl("ds-search", className),
		suppressHydrationWarning: true,
		...rest
	});
});
//#endregion
export { Search };
