'use client';
import { Suggestion } from "./suggestion.js";
import { SuggestionClear } from "./suggestion-clear.js";
import { SuggestionEmpty } from "./suggestion-empty.js";
import { SuggestionInput } from "./suggestion-input.js";
import { SuggestionList } from "./suggestion-list.js";
import { SuggestionOption } from "./suggestion-option.js";
import { SuggestionToggle } from "./suggestion-toggle.js";
//#region src/components/suggestion/index.ts
/**
* A component that provides a suggestion list for an input field.
*
* @example
* <Suggestion>
*   <Suggestion.Input />
*   <Suggestion.Toggle />
*   <Suggestion.Clear />
*   <Suggestion.List>
*     <Suggestion.Empty>Tomt</Suggestion.Empty>
*     <Suggestion.Option value='Option 1'>Option 1</Suggestion.Option>
*     <Suggestion.Option value='Option 2'>Option 2</Suggestion.Option>
*   </Suggestion.List>
* </Suggestion>
*/
const EXPERIMENTAL_Suggestion = Object.assign(Suggestion, {
	List: SuggestionList,
	Input: SuggestionInput,
	Empty: SuggestionEmpty,
	Option: SuggestionOption,
	Toggle: SuggestionToggle,
	Clear: SuggestionClear
});
EXPERIMENTAL_Suggestion.displayName = "EXPERIMENTAL_Suggestion";
EXPERIMENTAL_Suggestion.List.displayName = "EXPERIMENTAL_Suggestion.List";
EXPERIMENTAL_Suggestion.Input.displayName = "EXPERIMENTAL_Suggestion.Input";
EXPERIMENTAL_Suggestion.Empty.displayName = "EXPERIMENTAL_Suggestion.Empty";
EXPERIMENTAL_Suggestion.Option.displayName = "EXPERIMENTAL_Suggestion.Option";
EXPERIMENTAL_Suggestion.Toggle.displayName = "EXPERIMENTAL_Suggestion.Toggle";
EXPERIMENTAL_Suggestion.Clear.displayName = "EXPERIMENTAL_Suggestion.Clear";
//#endregion
export { EXPERIMENTAL_Suggestion, SuggestionClear as EXPERIMENTAL_SuggestionClear, SuggestionEmpty as EXPERIMENTAL_SuggestionEmpty, SuggestionInput as EXPERIMENTAL_SuggestionInput, SuggestionList as EXPERIMENTAL_SuggestionList, SuggestionOption as EXPERIMENTAL_SuggestionOption, SuggestionToggle as EXPERIMENTAL_SuggestionToggle };
